"""
	Return left_x and width of overlapping x of two rects
	"""
def find_x_overlap(rect1: Any, rect2: Any) -> object {
    r1left = rect1['left_x'];
    r1right = r1left + rect1['width'];
    r2left = rect2['left_x'];
    r2right = r2left + rect2['width'];
    highest_start_point = r1left if (r1left >= r2left) else r2left;
    lowest_end_point = r1right if (r1right <= r2right) else r2right;
    if (highest_start_point < lowest_end_point) {
        return (highest_start_point, (lowest_end_point - highest_start_point));
    } else {
        return None;
    }
}

"""Enables, or disables, the in-game music.  Useful if you want to use an MSU-1 soundtrack instead.

    Keyword Arguments:
        music {bool} -- If true, music is enabled.  If false, the music id disabled. (default: {True})

    Returns:
        list -- a list of dictionaries indicating which ROM address offsets to write and what to write to them
    """
def music(music: Any = True) -> object {
    return [{'1573402': [0 if music else 1]}];
}

"""
    Combine the image paths from `center`, `left` and `right` using the correction factor `correction`
    Returns ([imagePaths], [measurements])
    """
def CombineImages(
    center: Any, left: Any, right: Any, measurement: Any, correction: Any
) -> object {
    imagePaths = [];
    imagePaths.extend(center);
    imagePaths.extend(left);
    imagePaths.extend(right);
    measurements = [];
    measurements.extend(measurement);
    measurements.extend([(x + correction) for x in measurement]);
    measurements.extend([(x - correction) for x in measurement]);
    return (imagePaths, measurements);
}

"""Fibonacci example function

    Args:
      n (int): integer

    Returns:
      int: n-th Fibonacci number
    """
def fib(n: Any) -> object {
    assert (n > 0);
    (a, b) = (1, 1);
    for i in range((n - 1)) {
        (a, b) = (b, (a + b));
    }
    return a;
}

